{
  "meta": {
    "name": "Private Data App",
    "description": "A private application where users can view their own personalized data without needing to create an account."
  },
  "entities": [
    {
      "name": "UserData",
      "ownable": true,
      "fields": [
        {
          "name": "dataContent",
          "type": "text",
          "required": true
        }
      ]
    }
  ],
  "roles": [
    {
      "name": "user",
      "isDefault": true
    }
  ],
  "permissions": [
    {
      "role": "user",
      "entity": "UserData",
      "actions": [
        "create",
        "read",
        "update",
        "delete"
      ],
      "scope": "own"
    }
  ],
  "pages": [
    {
      "name": "My Data",
      "route": "/my-data",
      "type": "list",
      "entity": "UserData",
      "access": [
        "user"
      ]
    },
    {
      "name": "New Data Entry",
      "route": "/my-data/new",
      "type": "form",
      "entity": "UserData",
      "access": [
        "user"
      ]
    }
  ],
  "plans": [],
  "businessRules": [
    {
      "type": "ownership",
      "id": "userDataOwnership",
      "entity": "UserData"
    }
  ],
  "auth": {
    "strategy": "none",
    "requireAuth": false
  }
}
